 const AccountSelect=({required=false}:{required?:boolean})=><Field label={required?'Cuenta bancaria *':'Cuenta prevista'}><Choice label="Cuenta del registro" value={form.accountId||'none'} onChange={v=>{patch('accountId',v==='none'?null:v);setImportRows([])}} options={[...(!required?[{value:'none',label:'Sin asignar'}]:[]),...formAccounts.map(a=>({value:a.id,label:`${a.bank} · ${a.number}`}))]}/></Field>;
